import * as React from "react"
import { addPropertyControls, ControlType, RenderTarget } from "framer"

type LoadBridge = { isLoading: boolean; isComplete: boolean; progress?: number; setLoading?: () => void; setProgress?: (n: number) => void; setComplete?: () => void }
type LoadingWindow = Window & { __modelLoadingState?: LoadBridge; __preloadModel3D?: (url: string) => Promise<unknown>; __botanikaLoadingBoot?: { handoff: () => void } }
interface Props { logo?: string; model?: string; images?: string; accent?: string; background?: string; preview?: boolean; audience?: string; style?: React.CSSProperties }
const LOGO = "https://framerusercontent.com/images/WFpkEY4U2YfWmnJcO1hZ86XpVUQ.png"
const MODEL = "https://framerusercontent.com/assets/exkVGmXjcJJ49fgrMEM9l8NhEM.glb"
const IMAGES = ["https://framerusercontent.com/images/Hsh1gzdW7jeebdedw9uK0tlm8.png", "https://framerusercontent.com/images/EgH7gkf5tEj7PqdWjEfAstT8h4Q.png", "https://framerusercontent.com/images/SISGSkjCPtmS6V2h8aWOgR922DM.png", "https://framerusercontent.com/images/a3i1ToBatXHw86retpZP4HbO72c.png"]

/**
 * @framerIntrinsicWidth 390
 * @framerIntrinsicHeight 844
 * @framerSupportedLayoutWidth any-prefer-fixed
 * @framerSupportedLayoutHeight any-prefer-fixed
 */
export default function BotanikaLoading({ logo = LOGO, model = MODEL, images = IMAGES.join("\n"), accent = "#FE7426", background = "#080909", preview = false, audience = "Desktop", style }: Props) {
    const canvas = RenderTarget.current() === RenderTarget.canvas
    const dialog = React.useRef<HTMLDialogElement>(null)
    const [progress, setProgress] = React.useState(0)
    const [phase, setPhase] = React.useState("Loading assets")
    const [error, setError] = React.useState(false)
    const [leaving, setLeaving] = React.useState(false)
    const [done, setDone] = React.useState(false)
    const [attempt, setAttempt] = React.useState(0)
    const retry = () => { setDone(false); setLeaving(false); setError(false); setProgress(0); setAttempt(n => n + 1) }

    React.useEffect(() => {
        if (canvas || preview || done || typeof window === "undefined") return
        if ((window.innerWidth < 1200) !== (audience === "Phone")) return
        let cancelled = false, closing = false, failed = false, modelReady = false, parsed = false, documentReady = false, fontsReady = false, imagesDone = 0
        const win = window as LoadingWindow
        const timers = new Set<number>()
        const frames = new Set<number>()
        const pendingImages: HTMLImageElement[] = []
        const sources = Array.from(new Set([logo, ...images.split(/\n|,/).map(s => s.trim()).filter(Boolean)]))
        const delay = (fn: () => void, ms: number) => { const id = window.setTimeout(() => { timers.delete(id); if (!cancelled) fn() }, ms); timers.add(id); return id }
        const frame = (fn: () => void) => { const id = requestAnimationFrame(() => { frames.delete(id); if (!cancelled) fn() }); frames.add(id) }
        const stopScroll = (event: Event) => { if (!closing && event.cancelable) event.preventDefault() }
        const close = () => {
            if (closing || cancelled) return
            closing = true
            setLeaving(true)
            delay(() => { dialog.current?.close(); setDone(true) }, window.matchMedia("(prefers-reduced-motion: reduce)").matches ? 0 : 450)
        }
        const update = () => {
            if (cancelled || closing) return
            const value = (documentReady ? 5 : 0) + (fontsReady ? 5 : 0) + 20 * imagesDone / Math.max(1, sources.length) + (modelReady ? 70 : parsed ? 66 : 0)
            setProgress(old => Math.max(old, Math.min(99, Math.floor(value))))
            if (failed) return
            setPhase(!documentReady || !fontsReady || imagesDone < sources.length ? "Loading assets" : modelReady ? "Ready" : parsed ? "Preparing 3D scene" : "Loading NIMBUS")
            if (documentReady && fontsReady && imagesDone === sources.length && modelReady) {
                setProgress(100); setPhase("Ready")
                delay(close, 350)
            }
        }
        const fail = () => { if (!cancelled && !closing) { failed = true; setError(true); setPhase("Loading is taking longer than expected") } }
        try {
            const panel = dialog.current
            if (panel?.open) panel.close()
            panel?.showModal()
            // The early HTML loader stays visible until this modal has taken over
            if (panel?.open) win.__botanikaLoadingBoot?.handoff()
        } catch { fail() }
        window.addEventListener("wheel", stopScroll, { passive: false })
        window.addEventListener("touchmove", stopScroll, { passive: false })
        const previous = win.__modelLoadingState
        const initialComplete = previous?.isComplete === true
        const bridge: LoadBridge = {
            isLoading: !initialComplete, isComplete: initialComplete, progress: initialComplete ? 1 : 0,
            setLoading: () => { bridge.isLoading = true; previous?.setLoading?.() },
            setProgress: n => { bridge.progress = n; if (n >= .95 && n < 1) parsed = true; previous?.setProgress?.(n); update() },
            setComplete: () => { bridge.isComplete = true; bridge.isLoading = false; bridge.progress = 1; modelReady = true; parsed = true; previous?.setComplete?.(); update() },
        }
        win.__modelLoadingState = bridge
        modelReady = initialComplete
        const onLoad = () => { documentReady = true; update() }
        if (document.readyState === "complete") documentReady = true
        else window.addEventListener("load", onLoad, { once: true })
        Promise.resolve(document.fonts?.ready).then(() => { if (!cancelled) { fontsReady = true; update() } }, fail)
        for (const src of sources) {
            const image = new Image()
            pendingImages.push(image)
            image.onload = () => { Promise.resolve(image.decode?.()).catch(() => {}).then(() => { if (!cancelled) { imagesDone++; update() } }) }
            image.onerror = fail
            image.src = src
        }
        // Reuse the 3D runtime's own cache and readiness callback; never download a second GLB.
        let bridgeAttempts = 0
        const preload = () => {
            if (cancelled || modelReady) { update(); return }
            if (typeof win.__preloadModel3D !== "function") {
                if (++bridgeAttempts < 100) delay(preload, 100)
                else fail()
                return
            }
            Promise.resolve(win.__preloadModel3D(model)).then(() => {
                if (cancelled) return
                parsed = true
                if (bridge.isComplete) modelReady = true
                update()
            }, fail)
        }
        frame(() => frame(preload))
        delay(fail, 60000)
        update()
        return () => {
            cancelled = true
            timers.forEach(id => clearTimeout(id)); frames.forEach(id => cancelAnimationFrame(id))
            pendingImages.forEach(image => { image.onload = null; image.onerror = null })
            window.removeEventListener("load", onLoad)
            window.removeEventListener("wheel", stopScroll)
            window.removeEventListener("touchmove", stopScroll)
            dialog.current?.close()
            // Keep the bridge completion flags available for cached revisits; detach React callbacks.
            if (win.__modelLoadingState === bridge) win.__modelLoadingState = { isLoading: bridge.isLoading, isComplete: bridge.isComplete, progress: bridge.progress,
                setLoading() { this.isLoading = true }, setProgress(n) { this.progress = n }, setComplete() { this.isComplete = true; this.isLoading = false; this.progress = 1 } }
        }
    }, [canvas, preview, done, attempt, logo, model, images, audience])

    const displayProgress = preview ? 64 : progress
    const content = <div style={{ position: "relative", width: "100%", height: "100%", display: "flex", alignItems: "center", justifyContent: "center", background, color: "#F4F4F2", padding: 28, boxSizing: "border-box", opacity: leaving ? 0 : 1, transition: "opacity 450ms ease", fontFamily: '"Plus Jakarta Sans", Inter, sans-serif' }}>
        <div style={{ width: "min(320px, 100%)", display: "flex", flexDirection: "column", alignItems: "center" }}>
            <img src={logo} loading="eager" fetchPriority="high" alt="Botanika" width={203} height={40} style={{ width: 203, maxWidth: "80%", height: "auto", objectFit: "contain", marginBottom: 58 }} />
            <div style={{ width: "100%", display: "flex", alignItems: "baseline", justifyContent: "space-between", marginBottom: 15 }}>
                <span style={{ color: "#A5A5A4", fontSize: 11, letterSpacing: ".1em", textTransform: "uppercase" }} aria-hidden="true"></span>
                <span role="progressbar" aria-label="Loading Botanika" aria-valuemin={0} aria-valuemax={100} aria-valuenow={displayProgress} style={{ fontVariantNumeric: "tabular-nums", fontSize: 24, fontWeight: 500, letterSpacing: "-.04em" }}>{displayProgress}<span style={{ fontSize: 13, color: "#A5A5A4", marginLeft: 3 }}>%</span></span>
            </div>
            <div style={{ width: "100%", height: 2, background: "#262828", overflow: "hidden" }}><div style={{ height: "100%", width: `${displayProgress}%`, background: accent, transition: "width 300ms ease-out" }} /></div>
            <div aria-hidden="true" style={{ marginTop: 16, minHeight: 16 }} />
            {error && <div style={{ display: "flex", gap: 16, marginTop: 24 }}><button onClick={retry} style={{ border: "1px solid #434746", background: "transparent", color: "#F4F4F2", padding: "10px 16px", borderRadius: 4, cursor: "pointer" }}>Retry</button><button onClick={() => { dialog.current?.close(); setDone(true) }} style={{ border: 0, background: "transparent", color: "#A5A5A4", cursor: "pointer" }}>Continue to site</button></div>}
        </div>
    </div>
    if (canvas && !preview || done) return <div style={{ ...style, position: "relative", pointerEvents: "none" }} />
    if (preview) return <div style={{ ...style, position: "relative", width: "100%", height: "100%" }}>{content}</div>
    return <div style={{ ...style, position: "relative", pointerEvents: "none" }}><dialog ref={dialog} open aria-label="Loading Botanika" onCancel={event => event.preventDefault()} style={{ position: "fixed", inset: 0, margin: 0, padding: 0, width: "100vw", height: "100dvh", maxWidth: "none", maxHeight: "none", border: 0, overflow: "hidden", background, pointerEvents: "auto", zIndex: 2147483647 }}>{content}</dialog></div>
}
addPropertyControls(BotanikaLoading, {
    logo: { type: ControlType.File, title: "Logo", allowedFileTypes: ["png", "svg", "webp"] },
    model: { type: ControlType.File, title: "Model", allowedFileTypes: ["glb", "gltf"] },
    images: { type: ControlType.String, title: "Assets", displayTextArea: true, defaultValue: IMAGES.join("\n") },
    accent: { type: ControlType.Color, title: "Accent", defaultValue: "#FE7426" },
    background: { type: ControlType.Color, title: "Background", defaultValue: "#080909" },
    audience: { type: ControlType.Enum, title: "Breakpoint", options: ["Desktop", "Phone"], defaultValue: "Desktop" },
    preview: { type: ControlType.Boolean, title: "Design Preview", defaultValue: false },
})
